'use strict';

/**
* Generates random 32-bit unsigned integer seeds.
*
* This module generates random 32-bit unsigned integer seed values.
* These are used to seed the Xorshift128+ PRNG when no explicit seed
* is provided by the user.
*
* @private
* @returns {number} random 32-bit unsigned integer
*
* @example
* var seed = randi32();
* // returns <number>
*/

// MODULES //

var randu = require( '@stdlib/random/base/randu' );
var floor = require( '@stdlib/math/base/special/floor' );


// MAIN //

/**
* Generates a random 32-bit unsigned integer seed.
*
* @private
* @returns {number} random 32-bit unsigned integer
*
* @example
* var seed = randi32();
* // returns <number>
*/
function randi32() {
	/* eslint-disable no-magic-numbers */
	var seed = floor( randu() * 0x100000000 );

	/* eslint-enable no-magic-numbers */

	// Ensure non-zero seed
	if ( seed === 0 ) {
		seed = 1;
	}

	return seed >>> 0;  // Ensure unsigned 32-bit
}


// EXPORTS //

module.exports = randi32;
